    if not isinstance(parameters, dict) or not parameters:
        raise ValueError("Profile must contain learned feature parameters")
    for name, parameter in parameters.items():
        if not isinstance(name, str) or name.split(".", 1)[0] not in MODALITIES:
            raise ValueError("Unknown profile feature modality")
        if not isinstance(parameter, dict) or set(parameter) != {"center", "scale"}:
            raise ValueError(f"Invalid parameters for profile feature {name}")
        # Correlations and log ratios can be negative.
        if type(parameter["center"]) not in (int, float) or not math.isfinite(parameter["center"]):
