    if {name.split(".", 1)[0] for name in parameters} != set(MODALITIES):
        raise ValueError("Profile must contain features for every required modality")
    _finite_number(profile.get("threshold"), "threshold")
    if type(profile.get("alpha")) not in (int, float) or not 0 < profile["alpha"] < 1:
        raise ValueError("Profile alpha must be between 0 and 1")
    calibration = profile.get("calibration")
    if not isinstance(calibration, dict):
        raise ValueError("Missing calibration provenance")
    count, rank, scores = calibration.get("count"), calibration.get("rank"), calibration.get("sorted_scores")
    if type(count) is not int or count < 1 or type(rank) is not int or not 1 <= rank <= count:
        raise ValueError("Invalid calibration size/rank")
    if not isinstance(scores, list) or len(scores) != count:
        raise ValueError("Calibration score count does not match provenance")
    for score in scores:
        _finite_number(score, "calibration score")
    if scores != sorted(scores) or profile["threshold"] != scores[rank - 1]:
        raise ValueError("Profile threshold does not match stored calibration quantile")
    if rank != math.ceil((count + 1) * (1 - profile["alpha"])):
        raise ValueError("Profile calibration rank does not match alpha")
    return profile


