"""Strict event-format validation and relative behavioral measurements.

No contents, metadata, source labels, input-device identifiers or platform
identifiers enter the feature vector. Timing features use ratios or correlations
so that uniform time dilation leaves them unchanged (apart from input timestamp
rounding). Feature extraction is deterministic and has no learned state.
"""

from __future__ import annotations

import json
import math
from pathlib import Path
from statistics import mean, median, pstdev
from typing import Any


SCHEMA = "marrow.events.v1"
MODALITIES = ("pointer", "click", "text")
MIN_EVENTS = {"pointer": 12, "click": 5, "text": 8}
MIN_POSITIVE_INTERVALS = {"pointer": 10, "click": 4, "text": 7}


class RecordingError(ValueError):
    """The recording is not in the documented, finite-valued event format."""


def _reject_constant(value: str) -> None:
    raise RecordingError(f"Non-finite JSON number is not permitted: {value}")


def _unique_object(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
    result: dict[str, Any] = {}
    for key, value in pairs:
        if key in result:
            raise RecordingError(f"Duplicate JSON key: {key!r}")
        result[key] = value
    return result


def read_json(path: str | Path) -> Any:
    """Read strict JSON, rejecting NaN/Infinity and duplicate object keys."""
    try:
        return json.loads(
            Path(path).read_text(encoding="utf-8"),
            parse_constant=_reject_constant,
            object_pairs_hook=_unique_object,
        )
    except (UnicodeError, json.JSONDecodeError) as exc:
        raise RecordingError(f"Invalid UTF-8 JSON in {path}: {exc}") from exc


def _json_value(value: Any, location: str) -> None:
    """Also check in-memory callers; JSON encoders otherwise accept NaN."""
    if value is None or type(value) in (str, bool, int):
        return
    if type(value) is float:
        if not math.isfinite(value):
            raise RecordingError(f"{location}: number must be finite")
        return
    if isinstance(value, list):
        for index, item in enumerate(value):
            _json_value(item, f"{location}[{index}]")
        return
    if isinstance(value, dict):
        for key, item in value.items():
            if not isinstance(key, str):
                raise RecordingError(f"{location}: JSON object keys must be strings")
            _json_value(item, f"{location}.{key}")
        return
    raise RecordingError(f"{location}: unsupported JSON value {type(value).__name__}")


def _integer(value: Any, location: str) -> None:
    # bool is an int subclass in Python, but is not an event count/timestamp.
    if type(value) is not int or value < 0:
        raise RecordingError(f"{location}: expected a nonnegative integer")
    # Keeps later float-based statistics well-defined even for in-memory callers.
    if value > 2**53 - 1:
        raise RecordingError(f"{location}: exceeds the exact JSON integer range")


def _coordinate(value: Any, location: str) -> None:
    if type(value) not in (int, float):
        raise RecordingError(f"{location}: expected a finite coordinate")
    if not 0 <= value <= 1:  # Also rejects NaN; checks large integers before float conversion.
        raise RecordingError(f"{location}: coordinate must be between 0 and 1")


def validate_recording(recording: Any) -> dict[str, Any]:
    """Validate an in-memory recording without modifying or normalizing it.

    Metadata is arbitrary finite JSON, deliberately ignored by extraction. The
    root and event keys are strict so a misspelled input field cannot silently
    change the evidence available to the method.
    """
    if not isinstance(recording, dict):
        raise RecordingError("Recording must be a JSON object")
    if any(not isinstance(key, str) for key in recording):
        raise RecordingError("Recording field names must be strings")
    unknown = set(recording) - {"schema", "events", "metadata"}
    if unknown:
        raise RecordingError(f"Unknown recording fields: {sorted(unknown)}")
    if recording.get("schema") != SCHEMA:
        raise RecordingError(f"Expected schema {SCHEMA!r}")
    events = recording.get("events")
    if not isinstance(events, list):
        raise RecordingError("events must be a JSON array")
    if "metadata" in recording:
        _json_value(recording["metadata"], "metadata")
    last_time = -1
    for index, event in enumerate(events):
        location = f"events[{index}]"
        if not isinstance(event, dict):
            raise RecordingError(f"{location}: expected an object")
        if any(not isinstance(key, str) for key in event):
            raise RecordingError(f"{location}: field names must be strings")
        event_type = event.get("type")
        if event_type not in MODALITIES:
            raise RecordingError(f"{location}: unknown event type {event_type!r}")
        common = {"t_ms", "type"}
        if event_type in ("pointer", "click"):
            required = common | {"x", "y"}
            allowed = required | ({"button"} if event_type == "click" else set())
        else:
            required = common | {"origin", "action", "chars"}
            allowed = required | {"removed_chars"}
        missing = required - set(event)
        unknown = set(event) - allowed
        if missing or unknown:
            raise RecordingError(
                f"{location}: missing fields {sorted(missing)}; "
                f"unknown fields {sorted(unknown)}"
            )
        _integer(event["t_ms"], f"{location}.t_ms")
        if event["t_ms"] < last_time:
            raise RecordingError(f"{location}: timestamps must be nondecreasing")
        last_time = event["t_ms"]
        if event_type in ("pointer", "click"):
            _coordinate(event["x"], f"{location}.x")
            _coordinate(event["y"], f"{location}.y")
            if "button" in event and event["button"] not in ("primary", "secondary"):
                raise RecordingError(f"{location}: unknown click button")
        else:
            if event["origin"] not in ("typed", "on_screen", "software"):
                raise RecordingError(f"{location}: unknown text origin")
            if event["action"] not in ("insert", "delete", "replace"):
                raise RecordingError(f"{location}: unknown text action")
            _integer(event["chars"], f"{location}.chars")
            if "removed_chars" in event:
                _integer(event["removed_chars"], f"{location}.removed_chars")
