def _counts(event: dict[str, Any]) -> tuple[int, int]:
    """Return inserted and removed character counts, never actual text."""
    if event["action"] == "delete":
        return 0, event.get("removed_chars", event["chars"])
    return event["chars"], event.get("removed_chars", 0)



