def fit(enrollment, calibration):
    if len(enrollment) < 3 or len(calibration) < 2:
        raise ValueError('need at least 3 enrollment and 2 separate genuine calibration recordings')
    enrollment_hashes = {sha(Path(p).read_bytes()) for p in enrollment}
    calibration_hashes = {sha(Path(p).read_bytes()) for p in calibration}
    if len(enrollment_hashes) != len(enrollment) or len(calibration_hashes) != len(calibration):
        raise ValueError('duplicate recordings in fitting inputs')
    if enrollment_hashes & calibration_hashes:
        raise ValueError('enrollment/calibration leakage: identical recordings')
    vectors = [extract(load_recording(p)) for p in enrollment]
    centers, scales = [], []
    for index, floor in enumerate(FLOORS):
        column = [row[index] for row in vectors if row[index] is not None]
        if len(column) < 3:
            centers.append(None)
            scales.append(None)
            continue
        center = st.median(column)
        mad = st.median(abs(x - center) for x in column)
        centers.append(center)
        scales.append(max(floor, 1.4826 * mad))
    calibration_vectors = [extract(load_recording(p)) for p in calibration]
    # A variable feature must enlarge its own uncertainty, not the permitted
    # distance of every other feature. Only genuine, separate calibration
    # recordings enter this normalization. The held-out data remains unseen.
    for index, center in enumerate(centers):
        if center is None:
            continue
        residuals = [abs(row[index] - center) for row in calibration_vectors if row[index] is not None]
        if residuals:
            scales[index] = max(scales[index], max(residuals) / 2.5)
    profile = {'version': VERSION, 'features': FEATURES, 'center': centers, 'scale': scales,
               'protocol_sha256': sha(canonical(PROTOCOL).encode()),
               'fitting_recording_hashes': sorted(enrollment_hashes | calibration_hashes)}
    scores = [distance(profile, vector) for vector in calibration_vectors]
    profile.update(threshold=max(.8, 1.35 * max(scores) + .20), calibration_scores=scores,
                   threshold_frozen_before_heldout=True)
    return profile


def decide(profile, path):
    result = {'recording': Path(path).name, 'accepted': False}
    if profile.get('protocol_sha256') != sha(canonical(PROTOCOL).encode()):
        return dict(result, decision='abstain', reason='profile/protocol mismatch')
    if sha(Path(path).read_bytes()) in profile.get('fitting_recording_hashes', []):
        return dict(result, decision='abstain', reason='enrollment replay; not independent evidence')
    try:
