def fake_recording(style, person, condition, seed):
    """Synthetic motor hypotheses; not a simulator of any disability or device.

    A mimic matches the target's overall tempo and insertion batch sizes while
    retaining its own fine motor curvature and speed-shape. Exact behavioural
    copies are not distinguishable: the demo measures that counterexample too.
    """
    rng = random.Random(seed)
    target = person
    motor = 1 - person if condition in ('stranger', 'mimic') else person
    habits = target if condition == 'mimic' else motor
    tempo = (1.0, 1.45)[habits] * (2.4 if style == 'slow_inserted' else 1)
    if condition == 'tired':
        tempo *= 1.7
    bend = (.025, .20)[motor]
    shape = (1.05, 2.6)[motor]
    jitter = (.0008, .004)[motor] * (1.12 if condition == 'tired' else 1)
    events = []
    t = 0
    x, y = .5, .5
    for _ in range(16):
        x0, y0 = x, y
        tx, ty = rng.uniform(.15, .85), rng.uniform(.15, .85)
        dx, dy = tx - x0, ty - y0
        direction = rng.choice((-1, 1))
        duration = 500 * tempo * rng.uniform(.8, 1.2)
        for j in range(1, 9):
            u = (j / 8) ** shape
            x = max(0., min(1., x0 + dx * u - direction * dy * bend * math.sin(math.pi * u) + rng.gauss(0, jitter)))
            y = max(0., min(1., y0 + dy * u + direction * dx * bend * math.sin(math.pi * u) + rng.gauss(0, jitter)))
            t += max(1, round(duration / 8 * rng.uniform(.9, 1.1)))
            events.append({'t_ms': t, 'type': 'move', 'x': round(x, 6), 'y': round(y, 6)})
        t += max(1, round(80 * tempo * rng.uniform(.8, 1.2)))
        events.append({'t_ms': t, 'type': 'click', 'x': round(x, 6), 'y': round(y, 6), 'button': 'primary'})
        count = 5 if style == 'mouse_typed' else 2
        for _ in range(count):
            t += max(1, round(110 * tempo * rng.uniform(.7, 1.3)))
            amount = 1 if style == 'mouse_typed' else rng.choice((8, 12, 18)) + habits * 5
            deleted = int(rng.random() < (.08 if motor == 0 else .24))
            source = 'typed' if style == 'mouse_typed' else 'inserted'
            events.append({'t_ms': t, 'type': 'text', 'source': source,
                           'inserted': amount, 'deleted': deleted})
    return events


